                "webhook-signature"?: string;
                /** @description foresignal verifier */
                "X-Foresignal-Timestamp"?: string;
                /** @description foresignal verifier: `sha256=HMAC("<ts>.<body>")` */
                "X-Foresignal-Signature"?: string;
                /** @description CloudEvents binary mode attribute `id` */
                "ce-id"?: string;
                /** @description CloudEvents binary mode attribute `source` */
